import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易口诀义 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易口诀义 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/028.md","filePath":"zh/classics/koujueyi/028.md"}'),r={name:"zh/classics/koujueyi/028.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>彖曰：大畜，刚健笃实辉光，日新其德。刚上而尚贤，能止健，大正也。「不家食吉」，养贤也。利涉大川，应乎天也。象曰：天在山中，大畜。君子以多识前言往行，以畜其德。</p><p>初九：有厉利已。</p><p>象曰：「有厉利已」，不犯灾也。</p><p>九二：舆说輹。</p><p>象曰：「舆说輹」，中无尤也。</p><p>九三：良马逐，利艰贞。曰闲舆卫，利有攸往。</p><p>象曰：「利有攸往」，上合志也。</p><p>六四：童牛之牿，元吉。</p><p>象曰：六四「元吉」，有喜也。</p><p>六五：豮豕之牙，吉。</p><p>象曰：六五之「吉」，有庆也。</p><p>上九：何天之衢，亨。</p><p>象曰：「何天之衢」，道大行也。</p><p>解读</p><p>「大畜利贞」者，艮止于上，乾刚前进不得通，故曰「大畜」也。柔能制刚，非正不可，故曰「利贞」也。不家食吉，有大畜之财，常须养赡贤人，使贤德食禄，非食自家之食也。「利涉大川」者，丰财养贤，是合天之道，应人之心，故可济涉大川，不惧沉溺也。象曰「天在山中，大畜」者，艮山上止乾，阳不得通，故曰「大畜」也。「君子以多识前言往行，以畜其德」者，君子识前代人言往哲之行，使多闻多见，以畜积而为己德也。</p><p>初九，有厉，利已。已，止也。初欲前进，遇四畜盛，若进即有危厉，若休已不进，即有所利，故曰「有厉利已」。</p><p>九二，舆说輹。处畜之盛，不可前进，进而不已，则舆说輹败，不可以行。然九二有居中之德，不妄前进，岂有过尤哉？</p><p>九三，良马逐，利艰贞。曰闲舆卫，利有攸往者，夫「大畜」者，先畜后通，今处乾之上，畜道见通，可以升进。以上九有尚贤之德，而不拒于九三，三可以乘其壮马，驰骋而来，故曰「良马逐」。途路近通而未全泰，宜艰固而守贞正，故曰「利艰贞」。「曰闲舆卫」者，闲，碍也，卫，护也。虽日日见有人闲碍于舆，此则人之助己，乃是防卫见护也。何衢既通，小为阻碍，故无妨攸往。</p><p>六四：童牛之牿，元吉。童牛，一岁之牛，其角如茧栗。处艮之下，是畜之首。畜道将盛，初既止而不进，故六四可以童牛之角而止牿于初，以柔制刚，以息强争，非惟获其大吉，而亦有喜庆也。</p><p>六五：豮豕之牙，吉者，豕牙，横猾难制之物，谓九二也。九二前进，如豕之牙。五处畜盛而能制之，故豮制其牙使不前，能止强暴，非惟获胜，乃得吉庆，故云「有庆」。</p><p>上九：何天之衢，亨者，处畜之极，何须更畜，途径大通，无复为碍。衢者，四达之路。尔雅云「四达谓之衢」是也。</p>',22)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
